 WSLUA_METHOD Listener_remove(lua_State* L) {
-    /* Removes a tap `Listener`. */
+    /* Removes a tap `Listener`.
+       This function cannot be called from inside the tap's packet(),
+       draw(), or reset() callbacks; doing so would free the tap while
+       Wireshark is still using it. */
     Listener tap = checkListener(L,1);

+    if (tap == current_tap)
+        return luaL_error(L, "a Listener cannot be removed from within its own callback");
+
     if (listeners && g_ptr_array_remove(listeners, tap)) {
         deregister_Listener(L, tap);
     }
